package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.ServletException; import java.io.IOException; import java.sql.*;
@WebServlet("/orders")
public class OrdersServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{try{User u=(User)q.getSession().getAttribute("user");try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("SELECT order_id,total_amount,payment_status,order_status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC")){s.setInt(1,u.getUserId());try(ResultSet rs=s.executeQuery()){var list=new java.util.ArrayList<java.util.Map<String,Object>>();while(rs.next()){var m=new java.util.HashMap<String,Object>();m.put("id",rs.getInt("order_id"));m.put("total",rs.getBigDecimal("total_amount"));m.put("payment",rs.getString("payment_status"));m.put("status",rs.getString("order_status"));m.put("created",rs.getTimestamp("created_at"));list.add(m);}q.setAttribute("orders",list);}}q.getRequestDispatcher("/WEB-INF/views/orders.jsp").forward(q,r);}catch(Exception e){throw new ServletException(e);}}}
